css:
.loader { position: relative; width: var(--loader-size); height: calc(var(--loader-size) * .62); }
.loader span { position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: calc(var(--loader-size) * .08); background: var(--loader-color); animation: twStack calc(var(--loader-speed) * 2.1) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .7); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * 1.4); }
@keyframes twStack { 0% { transform: translateY(0) scale(1); opacity: 1; } 33% { transform: translateY(16%) scale(.92); opacity: .65; } 66% { transform: translateY(32%) scale(.84); opacity: .3; } 100% { transform: translateY(0) scale(1); opacity: 1; } }
